.search-item .l { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-item .l b { font-weight: 600; }
.search-item .s { font-size: 11.5px; color: var(--ink-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 260px; }
.search-foot { display: flex; gap: 14px; padding: 8px 14px; border-top: 1px solid var(--border); font-size: 11px; color: var(--ink-faint); }
.search-empty { padding: 16px; color: var(--ink-dim); }
.settings-popover { position: fixed; z-index: 40; top: calc(var(--topbar) + 6px); right: 12px; width: min(380px, calc(100vw - 24px)); background: var(--raised); border: 1px solid var(--border-strong); border-radius: var(--r-card); box-shadow: var(--shadow); padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; }
.field { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--ink-dim); }
.field input, .field select { height: 30px; padding: 0 8px; border: 1px solid var(--border); border-radius: var(--r-control); background: var(--bg); color: var(--ink); font: 12px var(--mono); }
.settings-popover .hint { margin: 0; font-size: 11.5px; color: var(--ink-faint); overflow-wrap: anywhere; }
.settings-actions { display: flex; justify-content: flex-end; gap: 8px; }
.toast { position: fixed; z-index: 70; bottom: calc(18px + env(safe-area-inset-bottom, 0px)); left: 50%; transform: translateX(-50%); background: var(--tint); color: var(--bg); border-radius: 999px; padding: 7px 14px; font-size: 12.5px; box-shadow: var(--shadow); }

/* Wide tables whose columns must not push each other off the edge. */
table.grid.fixed { table-layout: fixed; }
table.grid.fixed td { overflow-wrap: anywhere; }

/* MARK: Explorer (explorer.js): the tree and the open file in the view, the selected declaration in the inspector.
   Syntax colours are the one palette the site adds; they stay muted, so a highlighted line still reads as the ink. */
:root { --tk-k: #C3A6D9; --tk-t: #93B9DC; --tk-s: #D8B07A; --tk-n: #8CC79A; --xp-sig: rgba(229, 228, 226, 0.16); --xp-flash: rgba(147, 185, 220, 0.28); }
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) { --tk-k: #7346A0; --tk-t: #2D5E8E; --tk-s: #8A5A14; --tk-n: #36764A; --xp-sig: rgba(28, 28, 30, 0.1); --xp-flash: rgba(45, 94, 142, 0.18); }
}
:root[data-theme="light"] { --tk-k: #7346A0; --tk-t: #2D5E8E; --tk-s: #8A5A14; --tk-n: #36764A; --xp-sig: rgba(28, 28, 30, 0.1); --xp-flash: rgba(45, 94, 142, 0.18); }
.tk-k { color: var(--tk-k); } .tk-t { color: var(--tk-t); } .tk-s { color: var(--tk-s); } .tk-n { color: var(--tk-n); } .tk-c { color: var(--ink-faint); font-style: italic; }

/* The two panes stand at one height, the taller one's, up to what fits under the top bar with the keys line below them:
   their bottoms meet, and nothing covers the keys. Neither is sticky: a sticky tree slid down out of its row and over the
   keys line, since Chrome holds it only to the whole grid. */
.xp { --xp-pane: calc(100vh - var(--topbar) - var(--s5) - var(--s3) - 18px - var(--s7));
      display: grid; gap: var(--s3) var(--s4); align-items: start; grid-template-columns: minmax(200px, 250px) minmax(0, 1fr);
      grid-template-areas: "status status" "find find" "trail trail" "services services" "tree source" "keys keys"; scrollbar-color: var(--border-strong) transparent; }
.xp-status { grid-area: status; font: 11.5px/1.5 var(--mono); color: var(--ink-dim); overflow-wrap: anywhere; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; }
.xp-stale { flex-basis: 100%; margin: 0; font: 12.5px/1.45 var(--sans); color: var(--warn); }
.xp-check > summary { cursor: pointer; color: var(--ink-faint); }
.xp-check ul { list-style: none; margin: 6px 0 0; padding: 0; font: 12px/1.5 var(--sans); }
.xp-check li.bad { color: var(--bad); } .xp-check li.ok { color: var(--ink-dim); }
.xp-check p { margin: 6px 0 0; font-family: var(--sans); color: var(--ink); }
.xp-find { grid-area: find; min-width: 0; }
.xp-trail { grid-area: trail; min-width: 0; }
.xp-tree { grid-area: tree; min-width: 0; align-self: stretch; max-height: var(--xp-pane); overflow: auto; scrollbar-width: thin;
           border: 1px solid var(--border); border-radius: var(--r-card); background: var(--raised); }
.xp-source { grid-area: source; min-width: 0; align-self: stretch; max-height: var(--xp-pane); display: flex; flex-direction: column;
             border: 1px solid var(--border); border-radius: var(--r-card); background: var(--sunk); overflow: hidden; }
.xp-keys { grid-area: keys; margin: 0; font-size: 11.5px; line-height: 18px; color: var(--ink-faint); }
/* A hint wraps whole, never inside its phrase. */
.xp-keys > span { white-space: nowrap; }
.xp-hint { margin: 5px 0 0; font-size: 11.5px; color: var(--ink-faint); max-width: none; }
.xp-empty { margin: 0; color: var(--ink-dim); font-size: 12.5px; }

.xp-find-label { display: flex; align-items: flex-start; gap: 10px; font-size: 12.5px; color: var(--ink-dim); }
.xp-find-label > span { padding-top: 6px; }
.xp-find textarea { flex: 1; min-width: 0; resize: vertical; font: 12px/1.5 var(--mono); color: var(--ink); background: var(--bg); border: 1px solid var(--border-strong);
                    border-radius: var(--r-control); padding: 5px 8px; }
.xp-find .xp-hint { margin-left: 42px; }
.xp-results { list-style: none; margin: 6px 0 0; padding: 4px; max-height: 288px; overflow: auto; border: 1px solid var(--border); border-radius: var(--r-control); background: var(--raised); }
.xp-results li { padding: 5px 8px; border-radius: var(--r-chip); cursor: pointer; overflow-wrap: anywhere; }
.xp-results li b { display: block; font: 600 12px/1.4 var(--mono); }
.xp-results li small { display: block; font-size: 11px; color: var(--ink-dim); }
.xp-results li[aria-selected="true"] { background: var(--select); }
.xp-results li.xp-none { cursor: default; color: var(--ink-dim); }

/* The two trails, the walked one's steps, then where the walk stands. */
.xp-trails { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 8px; }
/* The loop: its name over the two lenses, and the asides that leave the step being walked. */
.xp-loop { margin: 0 0 6px; font-size: 12.5px; color: var(--ink-dim); }
.xp-loop b { color: var(--ink); }
.xp-asides { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 6px 0 0; font-size: 12px; color: var(--ink-dim); }
.xp-asides:empty { display: none; }
.xp-aside { display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px; font-size: 12px; }
.xp-aside-on { display: inline-flex; align-items: center; gap: 6px; color: var(--ink); }
.xp-trails button { display: inline-flex; align-items: baseline; flex-wrap: wrap; gap: 2px 8px; text-align: left; font: 12.5px/1.3 var(--sans); color: var(--ink-dim);
                    background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--r-control); padding: 6px 11px; cursor: pointer; }
.xp-trails button:hover { border-color: var(--ink-dim); }
.xp-trails button[aria-pressed="true"] { background: var(--select); border-color: var(--tint); color: var(--ink); }
.xp-trail-name { font-weight: 600; color: var(--ink); }
.xp-trail-sub { font-size: 11.5px; color: var(--ink-faint); }
.xp-steps { list-style: none; display: flex; flex-wrap: wrap; gap: 5px; margin: 0; padding: 0; }
.xp-steps button { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; font: 12px/1.3 var(--sans); color: var(--ink-dim); background: var(--raised);
                   border: 1px solid var(--border); border-radius: var(--r-control); padding: 5px 9px; cursor: pointer; }
.xp-steps button:hover { border-color: var(--border-strong); color: var(--ink); }
.xp-steps button[aria-pressed="true"] { background: var(--tint); color: var(--bg); border-color: var(--tint); }
.xp-steps .xp-n { font: 600 11px var(--mono); }
.xp-say-row { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; margin-top: 8px; }
.xp-say { margin: 0; font-size: 12.5px; color: var(--ink-dim); flex: 1 1 320px; }
.xp-say b { color: var(--ink); }
.xp-walks { display: inline-flex; flex-wrap: wrap; gap: 6px; margin: 0; }
.xp-link { all: unset; cursor: pointer; text-decoration: underline; text-decoration-color: var(--border-strong); text-underline-offset: 2px; overflow-wrap: anywhere; }
.xp-link:hover { text-decoration-color: currentColor; }
.xp-link:focus-visible { outline: 2px solid var(--tint); }

/* The tree: modules, folders, files, then a file's declarations. */
.xp-tree > .xp-files > summary { display: none; }
.xp-tree-inner { padding: 6px 4px 10px; font-size: 12.5px; }
.xp-tree details > summary { cursor: pointer; padding: 2px 6px; border-radius: var(--r-chip); list-style: none; display: flex; align-items: baseline; gap: 6px; }
.xp-tree details > summary::-webkit-details-marker { display: none; }
.xp-tree details > summary::before { content: "▸"; color: var(--ink-faint); font-size: 10px; transition: transform .12s; flex: none; }
.xp-tree details[open] > summary::before { transform: rotate(90deg); }
.xp-tree details > summary:hover { background: var(--hover); }
.xp-tree summary small { margin-left: auto; color: var(--ink-faint); font: 10.5px var(--mono); flex: none; }
.xp-node > summary { color: var(--ink); }
.xp-kids { padding-left: 10px; }
.xp-file > summary { color: var(--ink-dim); flex-wrap: wrap; }
.xp-fname { font: 12px var(--mono); overflow-wrap: anywhere; min-width: 0; }
.xp-badge { display: inline-block; flex: none; white-space: nowrap; min-width: 16px; text-align: center; font: 600 10px/1.45 var(--mono); color: var(--ink-dim);
            border: 1px solid var(--border-strong); border-radius: 3px; padding: 0 3px; margin-left: 3px; }
.xp-scopes { list-style: none; margin: 1px 0 4px; padding: 0 0 0 8px; }
.xp-scopes button { all: unset; box-sizing: border-box; display: flex; align-items: baseline; gap: 2px; width: 100%; cursor: pointer; padding: 1px 6px; border-radius: var(--r-chip);
                    font: 11.5px/1.45 var(--mono); color: var(--ink-dim); }
.xp-scopes button:hover { background: var(--hover); color: var(--ink); }
.xp-scopes button:focus-visible { outline: 2px solid var(--tint); }
.xp-scopes button[aria-current="true"] { background: var(--select); color: var(--ink); }
.xp-kind { flex: none; color: var(--tk-k); font-size: 10px; width: 40px; }
.xp-sname { min-width: 0; flex: 1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* The open file, whole, with the selected declaration lit. */
.xp-code-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 6px 12px; padding: 7px 10px; font: 11.5px/1.4 var(--mono); color: var(--ink-dim);
                border-bottom: 1px solid var(--border); background: var(--raised); }
.xp-path { overflow-wrap: anywhere; }
.xp-tools { display: inline-flex; flex-wrap: wrap; gap: 5px; }
.xp-tools .button { padding: 3px 8px; font: 11.5px var(--sans); text-decoration: none; }
.xp-tools .button[aria-pressed="true"] { background: var(--tint); color: var(--bg); border-color: var(--tint); }
.xp-tools .button[aria-disabled="true"] { opacity: 0.45; cursor: default; }
.xp-source pre { flex: 1 1 auto; min-height: 0; margin: 0; padding: 8px 0; overflow: auto; scrollbar-width: thin; font: 12px/1.55 var(--mono); tab-size: 4; outline: none; }
.xp-source pre:focus-visible { box-shadow: inset 0 0 0 2px var(--tint); }
.xp-source .ln { display: grid; grid-template-columns: 52px max-content; min-width: 100%; }
.xp-source .ln > span:first-child { color: var(--ink-faint); text-align: right; padding-right: 12px; user-select: none; }
.xp-source .ln > span:last-child { white-space: pre; padding-right: 16px; }
.xp-source .ln.sc > span:first-child { box-shadow: inset -2px 0 0 var(--border-strong); }
.xp-source .ln.hl { background: var(--select); }
.xp-source .ln.hl.doc { background: var(--hover); }
.xp-source .ln.sig { background: var(--xp-sig); }
.xp-source .ln.flash { background: var(--xp-flash); transition: background .3s; }
.xp-gap { font: 11px/1.9 var(--mono); color: var(--ink-faint); padding-left: 52px; }

/* The selected declaration, in the inspector. */
.xp-card .xp-title { font: 600 15px/1.35 var(--mono); margin: 0 0 4px; overflow-wrap: anywhere; }
.xp-card section { margin-top: var(--s4); }
.xp-card h4 { font: 600 10.5px/1.2 var(--sans); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-faint); margin: 10px 0 4px; }
.xp-card h3 small { font-weight: 400; letter-spacing: 0; }
.xp-kindline { margin: 0 0 10px; font-size: 12px; color: var(--ink-dim); overflow-wrap: anywhere; }
.xp-sig { margin: 0; padding: 8px 10px; font: 11.5px/1.5 var(--mono); background: var(--sunk); border: 1px solid var(--border); border-radius: var(--r-control); overflow-x: auto; white-space: pre; }
.xp-doc { margin: 0; font: 12.5px/1.5 var(--sans); white-space: pre-wrap; color: var(--ink-dim); }
.xp-cases { margin: 0; font: 11.5px/1.5 var(--mono); overflow-wrap: anywhere; }
.xp-on-trail { padding: 2px 12px 8px; border-left: 3px solid var(--tint); background: var(--band); border-radius: 0 var(--r-control) var(--r-control) 0; }
.xp-on-trail > h3 { margin-top: 10px !important; }
.xp-step-line { margin: 0 0 6px; font-size: 11.5px; color: var(--ink-dim); }
.xp-note { margin: 0 0 8px; font: 14px/1.55 var(--serif); color: var(--ink); }
.xp-links { margin: 0 0 6px; font-size: 11.5px; color: var(--ink-dim); overflow-wrap: anywhere; }
.xp-on-trail .xp-walks .button { padding: 3px 8px; font-size: 11.5px; }
.xp-header { margin-top: 6px; }
.xp-header > summary { cursor: pointer; font-size: 12px; color: var(--ink-dim); }
.xp-edges ul { list-style: none; margin: 3px 0 8px; padding: 0; }
.xp-edges li { padding: 2px 0; font: 11.5px/1.45 var(--mono); overflow-wrap: anywhere; }
.xp-edges li small { color: var(--ink-faint); }
.xp-at { all: unset; cursor: pointer; color: var(--ink-faint); font-size: 10.5px; }
.xp-at:hover { color: var(--ink); }
.xp-at:focus-visible { outline: 2px solid var(--tint); }
.tier { display: inline-block; font: 600 10px/1.5 var(--sans); letter-spacing: 0.05em; text-transform: uppercase; }
.tier-exact { color: var(--ok); } .tier-likely { color: var(--warn); } .tier-ambiguous { color: var(--ink-faint); }
.tier-flow { color: var(--ink); background: var(--select); padding: 0 5px; border-radius: var(--r-chip); }
/* How a trail entry is reached: the Granite flow, or the call, from the entry that reaches it. */
.xp-hop { margin: 0 0 6px; font-size: 12px; line-height: 1.5; color: var(--ink-dim); overflow-wrap: anywhere; }
.xp-hop .xp-link { font-family: var(--mono); font-size: 11.5px; }
.xp-hop-word { font: 600 10px/1.5 var(--sans); letter-spacing: 0.05em; text-transform: uppercase; color: var(--ink); white-space: nowrap; }
.xp-honest { margin-top: var(--s4); }

@media (max-width: 1240px) { .xp { grid-template-columns: minmax(180px, 220px) minmax(0, 1fr); } }
@media (max-width: 860px) {
  .xp { grid-template-columns: minmax(0, 1fr); grid-template-areas: "status" "find" "trail" "services" "tree" "source" "keys"; }
  .xp-tree, .xp-source { max-height: none; }
  .xp-tree > .xp-files > summary { display: flex; padding: 8px 10px; font-weight: 600; }
  .xp-tree > .xp-files[open] > summary { border-bottom: 1px solid var(--border); }
  .xp-source pre { max-height: 70vh; }
  .xp-steps .xp-t, .xp-steps .xp-phase { display: none; }
  .xp-steps button { min-width: 34px; justify-content: center; }
  .xp-find .xp-hint { margin-left: 0; }
  .xp-find-label { flex-direction: column; align-items: stretch; gap: 4px; }
  .xp-find-label > span { padding-top: 0; }
  .xp-keys { display: none; }
}
@media (prefers-reduced-motion: reduce) { .xp-source .ln.flash { transition: none; } }

/* MARK: Ask (ask.js): half seen until a pointer or focus finds it, then a mini chat that folds back into it. */
.ask-orb { position: fixed; right: 18px; bottom: calc(18px + env(safe-area-inset-bottom, 0px)); z-index: 60; width: 44px; height: 44px; padding: 0; border: 1px solid var(--border-strong);
           border-radius: 50%; cursor: pointer; opacity: 0.5; background: radial-gradient(circle at 34% 30%, var(--ink) 0, var(--tint) 22%, var(--ink-dim) 58%, var(--raised) 100%);
           box-shadow: var(--shadow); transition: opacity .2s ease, transform .2s ease; }
.ask-orb:hover, .ask-orb:focus-visible { opacity: 1; transform: scale(1.06); }
.ask-orb:focus-visible { outline: 2px solid var(--tint); outline-offset: 3px; }
.ask { position: fixed; right: 18px; bottom: calc(18px + env(safe-area-inset-bottom, 0px)); z-index: 60; width: min(384px, calc(100vw - 24px)); height: min(544px, calc(100vh - 36px));
       display: flex; flex-direction: column; overflow: hidden; color: var(--ink); background: var(--raised); border: 1px solid var(--border-strong);
       border-radius: var(--r-sheet); box-shadow: var(--shadow); transform-origin: 100% 100%; animation: ask-in .18s ease-out; }
@keyframes ask-in { from { opacity: 0; transform: scale(.25); border-radius: 50%; } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .ask { animation: none; } .ask-orb { transition: none; } }
.ask-head { display: flex; align-items: center; gap: 10px; padding: 10px 10px 9px 14px; border-bottom: 1px solid var(--border); }
.ask-dot { flex: none; width: 16px; height: 16px; border-radius: 50%; background: radial-gradient(circle at 34% 30%, var(--ink) 0, var(--tint) 22%, var(--ink-dim) 58%, var(--raised) 100%); }
.ask-title { flex: 1; min-width: 0; }
.ask-title b { display: block; font-size: 13px; line-height: 1.2; }
.ask-about { display: block; font: 11px/1.4 var(--mono); color: var(--ink-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ask-close { all: unset; flex: none; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; cursor: pointer; color: var(--ink-dim); font-size: 18px; }
.ask-close:hover { background: var(--hover); color: var(--ink); }
.ask-close:focus-visible, .ask-new:focus-visible { outline: 2px solid var(--tint); }
.ask-new { flex: none; font: 11.5px var(--sans); color: var(--ink-dim); background: var(--bg); border: 1px solid var(--border-strong); border-radius: 999px; padding: 3px 10px; cursor: pointer; }
.ask-new:hover:not(:disabled) { color: var(--ink); border-color: var(--ink-dim); }
.ask-new:disabled { opacity: 0.4; cursor: default; }
.ask-log { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; padding: 12px 14px; font-size: 13px; line-height: 1.5; }
.ask-msg { max-width: 92%; overflow-wrap: anywhere; }
.ask-msg.user { align-self: flex-end; padding: 7px 11px; border-radius: 12px 12px 3px 12px; background: var(--tint); color: var(--bg); white-space: pre-wrap; }
.ask-msg.bot { align-self: flex-start; }
.ask-msg.bot p { margin: 0 0 8px; }
.ask-msg.bot p:last-child, .ask-msg.bot ul:last-child, .ask-msg.bot ol:last-child { margin-bottom: 0; }
.ask-msg.bot ul, .ask-msg.bot ol { margin: 0 0 8px; padding-left: 18px; }
.ask-msg.error p { color: var(--bad); font-size: 12.5px; }
.ask-msg.note { align-self: center; max-width: 100%; margin: 0; text-align: center; color: var(--ink-dim); font-size: 11.5px; }
.ask-aside { color: var(--ink-dim); font-size: 11.5px; }
.ask-wait { color: var(--ink-dim); font-style: italic; }
.ask-reads { margin: 0 0 7px; font-size: 11px; line-height: 1.5; color: var(--ink-dim); }
.ask-reads a, .ask-reads span { font: 11px var(--mono); }
.ask-code { margin: 4px 0 10px; padding: 8px 10px; overflow-x: auto; white-space: pre; font: 11.5px/1.5 var(--mono); background: var(--sunk); border: 1px solid var(--border); border-radius: var(--r-control); }
.ask-starters { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.ask-starters button { font: 12px var(--sans); color: var(--ink-dim); background: var(--bg); border: 1px solid var(--border-strong); border-radius: 999px; padding: 4px 11px; cursor: pointer; }
.ask-starters button:hover { color: var(--ink); border-color: var(--ink-dim); }
.ask-setup p { margin: 0 0 10px; font-size: 12.5px; color: var(--ink-dim); }
.ask-keyrow { display: flex; gap: 6px; }
.ask-keyrow input { flex: 1; min-width: 0; font: 12px var(--mono); color: var(--ink); background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--r-control); padding: 6px 8px; }
.ask-keyrow button, .ask-form button { font: 600 12.5px var(--sans); color: var(--bg); background: var(--tint); border: 0; border-radius: var(--r-control); padding: 7px 12px; cursor: pointer; }
.ask-form { display: flex; align-items: flex-end; gap: 7px; padding: 10px 11px 8px; border-top: 1px solid var(--border); }
.ask-form textarea { flex: 1; min-width: 0; max-height: 128px; resize: none; font: 13px/1.4 var(--sans); color: var(--ink); background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--r-control); padding: 7px 9px; }
.ask-form button:disabled { opacity: 0.4; cursor: default; }
.ask-foot { margin: 0; padding: 0 14px 9px; font-size: 10.5px; line-height: 1.4; color: var(--ink-faint); }
.ask-link { all: unset; cursor: pointer; text-decoration: underline; color: var(--ink-dim); }
@media (max-width: 860px) { .ask { right: 12px; bottom: 12px; } .ask-orb { right: 14px; bottom: 14px; } }
@media print { .ask-orb, .ask { display: none !important; } }

/* MARK: Additions for any codebase: the services strip in the Explorer, a doc's images, a source with no Swift. */
.xp-services { grid-area: services; min-width: 0; }
.xp-services > summary { font-size: 12.5px; }
.xp-services > summary b { color: var(--ink); }
.xp-service-list { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.xp-service-list li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; font-size: 12px; }
.xp-service-list .xp-rank { font: 600 10.5px/1.5 var(--mono); color: var(--ink-faint); min-width: 18px; }
.xp-service-list .xp-sv { font: 600 12px var(--mono); }
.xp-service-list .chip { cursor: pointer; }
.xp-service-list .xp-relays { flex-basis: 100%; padding-left: 26px; color: var(--ink-faint); font-size: 11.5px; }
.doc-page img { max-width: 100%; height: auto; border-radius: var(--r-control); }
.doc-image { color: var(--ink-dim); font-size: 12.5px; }
.lang-chip { margin-left: 6px; }
.dot-list { margin: 0; padding-left: 1.1em; }
.dot-list li { margin: 2px 0; }

